-- SYNTHETIC DEMONSTRATION DATA ONLY. Not official or operational Lucena City data.
on conflict(psgc_code) do nothing;
select id,population,round(population/4.2),4.2,round(population*.28),round(population*.08),round(population*.04),'Project AGAP synthetic demonstration dataset',2026,true from public.barangays where is_demo on conflict do nothing;
on conflict(name,version) do nothing;
values ('40000000-0000-4000-8000-000000000001','SYNTHETIC — Project AGAP Demo','Severe Rainfall Demonstration','DEMO-BULLETIN-001','Synthetic heavy-rainfall scenario for software demonstration only.',now(),now()-interval '1 hour',now()+interval '365 days',array['Dalahican','Cotta','Barra'],'https://example.invalid/agap-demo','VERIFIED',true)
on conflict(source_agency,bulletin_reference) do update set validity_end=excluded.validity_end;
select id,800,200,20,'{"vehicles":2,"radios":8}','UNVERIFIED',array['SMS','Radio','Barangay Announcements'],'FOR_REVIEW',current_date,'Project AGAP synthetic demonstration dataset',array['Synthetic capacities require replacement and LGU validation.'],true from public.barangays where is_demo and not exists(select 1 from public.preparedness_capacities p where p.barangay_id=barangays.id);
select b.id,'20000000-0000-4000-8000-000000000001',round(b.population*.35),round(b.population*.35/4.2),'{"children":980,"older_persons":280,"persons_with_disabilities":140}','INHABITED_AREA_PROPORTION_FALLBACK','LOW','Project AGAP synthetic demonstration estimate',current_date,array['Pre-disaster estimate only; not affected population and not household-level exposure.'],true from public.barangays b where b.is_demo and not exists(select 1 from public.population_exposure_estimates e where e.barangay_id=b.id);
select 'Synthetic '+barangay_name+' Evacuation Facility','EVACUATION_CENTER',id,'UNVERIFIED',500,'Project AGAP synthetic demonstration dataset',true from public.barangays b where b.is_demo and not exists(select 1 from public.critical_facilities f where f.barangay_id=b.id);
values ('DLH-P03-HH0048','10000000-0000-4000-8000-000000000001','Purok 3',5,true,true,false,true,true,'{"type":"synthetic demo profile"}',array['SMS','Radio'],true) on conflict(household_code) do nothing;
on conflict(rule_id,version) do nothing;

on conflict(rule_id,version) do nothing;

select gen_random_uuid(),b.id,'40000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001',3,4,12,'HIGH',3,2,1.5,'["Synthetic demonstration input only"]',current_date,'LOW',array['Replace all values with verified operational evidence.'] from public.barangays b where b.is_demo and not exists(select 1 from public.risk_assessments r where r.barangay_id=b.id);
select gen_random_uuid(),id,25,6,'{"older_persons":2}','Synthetic flood damage report','UNDETERMINED','UNVERIFIED','UNVERIFIED','[{"type":"note","reference":"Synthetic demo evidence"}]','Project AGAP synthetic demonstration dataset',now(),now(),'UNVERIFIED','SYNCED',true from public.barangays where barangay_name='Dalahican' and not exists(select 1 from public.damage_reports where is_demo);
select id,true,true,true,'HIGH','Project AGAP synthetic demonstration dataset','UNVERIFIED',true from public.barangays where barangay_name='Dalahican' and not exists(select 1 from public.needs_reports where is_demo);
select '40000000-0000-4000-8000-000000000001','DEMO-EVENT-001',id,25,0,6,0,'{"reported":"Synthetic demo only"}','Synthetic report awaiting validation','UNVERIFIED','UNVERIFIED','UNVERIFIED','Water, shelter, and medicine reports awaiting validation','UNVERIFIED','OPEN' from public.barangays where barangay_name='Dalahican' and not exists(select 1 from public.post_impact_reviews where event_reference='DEMO-EVENT-001');
